const crypto = require("crypto");
const rawBody = String(input.rawBody || "");
const timestamp = String(input.timestamp || "");
const signature = String(input.signature || "");
const secret = String(input.secret || "");
const stamped = Number(timestamp);
const now = Math.floor(Date.now() / 1000);
if (!Number.isFinite(stamped) || Math.abs(now - stamped) > 300) {
  throw new Error("timestamp outside replay window");
}
const payload = timestamp + "." + rawBody;
const expected = "v1=" + crypto.createHmac("sha256", secret).update(payload).digest("hex");
if (expected.length !== signature.length) throw new Error("signature mismatch");
let diff = 0;
for (let i = 0; i < expected.length; i += 1) diff |= expected.charCodeAt(i) ^ signature.charCodeAt(i);
if (diff !== 0) throw new Error("signature mismatch");
const event = JSON.parse(rawBody);
if (event.type !== "call.missed") throw new Error("unexpected event type");
return event;
